    75	
    76	        DataStream<Tuple2<Long, Integer>> result = submits
    77	                .connect(finishes)
    78	                .keyBy(
    79	                        new KeySelector<TaskEvent, Long>() {
    80	                            @Override
    81	                            public Long getKey(TaskEvent e) {
    82	                                return e.jobId;
    83	                            }
    84	                        },
    85	                        new KeySelector<JobEvent, Long>() {
    86	                            @Override
    87	                            public Long getKey(JobEvent e) {
    88	                                return e.jobId;
    89	                            }
    90	                        })
    91	                .process(new StageProcessor(sessionGapMicros))
    92	                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Integer>>() {}));
    93	
    94	        @SuppressWarnings({"unchecked", "rawtypes"})
    95	        SinkFunction<String> sink = (SinkFunction<String>) sinkOrTest(new TextFileSink(outputPath));
    96	
    97	        result.map(new MapFunction<Tuple2<Long, Integer>, String>() {
    98	            @Override
    99	            public String map(Tuple2<Long, Integer> t) {
   100	                return "(" + t.f0 + "," + t.f1 + ")";
   101	            }
   102	        }).addSink(sink);
   103	
   104	        env.execute("LongestSessionPerJob");
   105	    }
