   107	    /**
   108	     * Tracks task stages per job and emits the (jobId, longestStageSize) tuple once
   109	     * the job has finished. A stage is a run of SUBMIT events whose consecutive
   110	     * event-time gap is less than {@code sessionGapMicros}.
   111	     */
   112	    public static class StageProcessor
   113	            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {
   114	
   115	        private final long sessionGapMicros;
   116	
   117	        private transient ValueState<Long> lastSubmitTime;
   118	        private transient ValueState<Integer> currentStageCount;
   119	        private transient ValueState<Integer> maxStageCount;
   120	        private transient ValueState<Boolean> finished;
   121	
   122	        public StageProcessor(long sessionGapMicros) {
   123	            this.sessionGapMicros = sessionGapMicros;
   124	        }
   125	
   126	        @Override
   127	        public void open(Configuration parameters) {
   128	            lastSubmitTime = getRuntimeContext().getState(
   129	                    new ValueStateDescriptor<>("lastSubmitTime", Long.class));
   130	            currentStageCount = getRuntimeContext().getState(
   131	                    new ValueStateDescriptor<>("currentStageCount", Integer.class));
   132	            maxStageCount = getRuntimeContext().getState(
   133	                    new ValueStateDescriptor<>("maxStageCount", Integer.class));
   134	            finished = getRuntimeContext().getState(
   135	                    new ValueStateDescriptor<>("finished", Boolean.class));
   136	        }
   137	
   138	        @Override
   139	        public void processElement1(TaskEvent event, Context ctx,
   140	                                    Collector<Tuple2<Long, Integer>> out) throws Exception {
   141	            long t = event.timestamp;
   142	            Long last = lastSubmitTime.value();
   143	            int current = currentStageCount.value() == null ? 0 : currentStageCount.value();
   144	            int max = maxStageCount.value() == null ? 0 : maxStageCount.value();
   145	
   146	            if (last != null && (t - last) >= sessionGapMicros) {
   147	                // The previous stage ended 10+ minutes ago; close it and start a new one.
   148	                if (current > max) {
   149	                    max = current;
   150	                }
   151	                current = 0;
   152	            }
   153	            current++;
   154	            lastSubmitTime.update(t);
   155	            currentStageCount.update(current);
   156	            maxStageCount.update(max);
   157	
   158	            // Make sure we fire the final-emission timer even if the FINISH event
   159	            // for this job arrives before any SUBMIT does (unlikely, but safe).
   160	            ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE);
   161	        }
   162	
   163	        @Override
   164	        public void processElement2(JobEvent event, Context ctx,
   165	                                    Collector<Tuple2<Long, Integer>> out) throws Exception {
   166	            finished.update(true);
   167	            ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE);
   168	        }
   169	
   170	        @Override
   171	        public void onTimer(long timestamp, OnTimerContext ctx,
   172	                            Collector<Tuple2<Long, Integer>> out) throws Exception {
   173	            Boolean isFinished = finished.value();
   174	            if (isFinished == null || !isFinished) {
   175	                return;
   176	            }
   177	
   178	            int current = currentStageCount.value() == null ? 0 : currentStageCount.value();
   179	            int max = maxStageCount.value() == null ? 0 : maxStageCount.value();
   180	            if (current > max) {
   181	                max = current;
   182	            }
   183	            if (max > 0) {
   184	                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
   185	            }
   186	        }
   187	    }
