   189	    /**
   190	     * Minimal sink that appends each record to a local file on one line. Used only
   191	     * when the pipeline runs with parallelism = 1, which is the case for this job.
   192	     */
   193	    public static class TextFileSink implements SinkFunction<String> {
   194	
   195	        private final String path;
   196	        private transient BufferedWriter writer;
   197	
   198	        public TextFileSink(String path) {
   199	            this.path = path;
   200	        }
   201	
   202	        @Override
   203	        public void invoke(String value, Context context) throws Exception {
   204	            if (writer == null) {
   205	                writer = new BufferedWriter(new FileWriter(path, false));
   206	                Runtime.getRuntime().addShutdownHook(new Thread(() -> {
   207	                    try {
   208	                        writer.flush();
   209	                        writer.close();
   210	                    } catch (Exception ignored) {
   211	                    }
   212	                }));
   213	            }
   214	            writer.write(value);
   215	            writer.newLine();
   216	            writer.flush();
   217	        }
   218	    }
   219	}
